import * as aws from "@pulumi/aws";

// Placeholder resource so the stack has something to preview. Replace this with
// the real payments infrastructure.
//
// Standard tags (team, service, env, cost-center, managed-by) are applied to
// every AWS resource automatically via `aws:defaultTags`, set in the
// payments/base and payments/dev ESC environments — don't tag resources by hand.
const artifacts = new aws.s3.Bucket("payments-artifacts");

export const artifactsBucket = artifacts.bucket;
